// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";

/// @title DatabaseDriver - On-chain key-value store with audit logging
/// @notice Provides symlink-like references between storage slots
contract DatabaseDriver is Ownable {
    struct Record {
        bytes32 data;
        uint256 timestamp;
        address writer;
        bool isLink;       // if true, 'data' points to another key
        bool exists;
    }

    struct AuditEntry {
        address actor;
        bytes32 key;
        bytes32 value;
        uint256 blockNum;
        string operation;
    }

    mapping(bytes32 => Record) private _store;
    mapping(address => bool) public authorized;
    AuditEntry[] public auditLog;

    uint256 public constant MAX_LINK_DEPTH = 8;
    mapping(bytes32 => bool) private _locked;

    event DataWritten(bytes32 indexed key, bytes32 value);
    event LinkCreated(bytes32 indexed from, bytes32 indexed to);
    event AuditLogged(uint256 indexed entryId, string operation);

    modifier onlyAuthorized() {
        require(authorized[msg.sender] || msg.sender == owner(), "Unauthorized");
        _;
    }

    modifier notLocked(bytes32 key) {
        require(!_locked[key], "Key is locked");
        _;
    }

    constructor() Ownable(msg.sender) {
        authorized[msg.sender] = true;
    }

    function authorize(address user) external onlyOwner {
        authorized[user] = true;
        _appendAudit(msg.sender, bytes32(uint256(uint160(user))), bytes32(0), "AUTHORIZE");
    }

    function revoke(address user) external onlyOwner {
        authorized[user] = false;
        _appendAudit(msg.sender, bytes32(uint256(uint160(user))), bytes32(0), "REVOKE");
    }

    function write(bytes32 key, bytes32 value) external onlyAuthorized notLocked(key) {
        _store[key] = Record(value, block.timestamp, msg.sender, false, true);
        _appendAudit(msg.sender, key, value, "WRITE");
        emit DataWritten(key, value);
    }

    /// @notice Create a symbolic link from 'linkKey' to 'targetKey'
    function createLink(bytes32 linkKey, bytes32 targetKey) external onlyAuthorized notLocked(linkKey) {
        require(linkKey != targetKey, "Self-link not allowed");
        _store[linkKey] = Record(targetKey, block.timestamp, msg.sender, true, true);
        _appendAudit(msg.sender, linkKey, targetKey, "CREATE_LINK");
        emit LinkCreated(linkKey, targetKey);
    }

    /// @notice Resolve a key, following symlinks up to MAX_LINK_DEPTH
    function resolve(bytes32 key) public view returns (bytes32 finalKey, bytes32 data) {
        bytes32 current = key;
        for (uint256 i = 0; i < MAX_LINK_DEPTH; i++) {
            Record storage rec = _store[current];
            if (!rec.exists) {
                return (current, bytes32(0));
            }
            if (!rec.isLink) {
                return (current, rec.data);
            }
            current = rec.data;
        }
        revert("Link depth exceeded");
    }

    /// @notice Write through a symlink chain - resolves then writes to final target
    function writeThrough(bytes32 key, bytes32 value) external onlyAuthorized {
        (bytes32 finalKey, ) = resolve(key);
        // NOTE: lock check uses the ORIGINAL key, not the resolved key
        require(!_locked[key], "Source key is locked");
        _store[finalKey] = Record(value, block.timestamp, msg.sender, false, true);
        _appendAudit(msg.sender, key, value, "WRITE_THROUGH");
        emit DataWritten(finalKey, value);
    }

    /// @notice Lock a key to prevent modifications
    function lockKey(bytes32 key) external onlyOwner {
        _locked[key] = true;
        _appendAudit(msg.sender, key, bytes32(0), "LOCK");
    }

    /// @notice Read with full audit trail
    function auditedRead(bytes32 key) external returns (bytes32) {
        (bytes32 finalKey, bytes32 data) = resolve(key);
        _appendAudit(msg.sender, finalKey, data, "READ");
        return data;
    }

    function getAuditLogLength() external view returns (uint256) {
        return auditLog.length;
    }

    function getRecord(bytes32 key) external view returns (Record memory) {
        return _store[key];
    }

    function _appendAudit(
        address actor,
        bytes32 key,
        bytes32 value,
        string memory operation
    ) internal {
        auditLog.push(AuditEntry({
            actor: actor,
            key: key,
            value: value,
            blockNum: block.number,
            operation: operation
        }));
        emit AuditLogged(auditLog.length - 1, operation);
    }
}
